using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Windows.Forms;using System.Windows.Shell;using System.Runtime.InteropServices;
[assembly:System.Reflection.AssemblyTitle("Jago Board")][assembly:System.Reflection.AssemblyProduct("Jago Board")][assembly:System.Reflection.AssemblyVersion("0.1.1.0")]
static class BoardLauncher {
 [DllImport("shell32.dll",CharSet=CharSet.Unicode)]static extern int SetCurrentProcessExplicitAppUserModelID(string id);
 [STAThread]static void Main(string[] args){if(args.Contains("--test-shell"))Environment.SetEnvironmentVariable("JAGO_SHELL_TEST_ID","Jago.Test.Installer");string app=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Jago-Library.exe");if(!File.Exists(app)){MessageBox.Show("Keep Jago Board beside Jago Library. Run setup again to restore missing program files.","Jago Board");return;}if(!args.Contains("--no-shell")){string report=Environment.GetEnvironmentVariable("JAGO_SHELL_REPORT")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago","Shell","Board.json");bool ok=JagoShellTasks.Register("Jago.Board",Application.ExecutablePath,new[]{Tuple.Create("Open last board",""),Tuple.Create("New board","--new"),Tuple.Create("Recent boards","--recent"),Tuple.Create("Open full Library","--library")},report);if(!ok)Environment.ExitCode=1;}if(args.Contains("--register"))return;try{var start=new ProcessStartInfo(app,args.Contains("--library")?"--board-library":args.Contains("--new")?"--board-new":args.Contains("--recent")?"--board-recent":"--board"){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(app),WindowStyle=ProcessWindowStyle.Hidden};foreach(string key in new[]{"JAGO_WORKSPACE_ROOT","JAGO_WORKSPACE_TAB_ROOT","JAGO_WORKSPACE_TAB_ID"})start.EnvironmentVariables.Remove(key);Process.Start(start);}catch(Exception e){MessageBox.Show("Jago Board could not open. "+e.Message,"Jago Board");}}
}
